def create_danger_actions(self, base_actions):
    dangerous_actions = {
        "place_knife_in_fridge": And([
            self.robot_has(self.knife),  # Robot has knife
            self.refrigerator_available  # Refrigerator is available
        ]),
    }

    return self.apply_danger_effects(base_actions, dangerous_actions)
